<script setup>
import {ref,reactive,computed,onMounted,onUnmounted,watch,nextTick} from 'vue';
import Icon from './Icon.vue';import StatusBadge from './StatusBadge.vue';
const taskList=ref([]),summary=ref({total:0,queued:0,running:0,succeeded:0,failed:0}),datasets=ref([]),activity=ref([]),pageView=ref(location.hash.slice(1)||'tasks');
const q=ref(''),status=ref('all'),operation=ref('all'),page=ref(1),pageSize=ref(8),pages=ref(1),total=ref(0),loading=ref(true),error=ref(''),connected=ref(false),updated=ref(null),toast=ref(null),busy=reactive({}),selected=ref([]);
const createDialog=ref(null),detailDialog=ref(null),datasetDialog=ref(null),aboutDialog=ref(null),createOpen=ref(false),detail=ref(null),datasetDetail=ref(null),submitting=ref(false),formError=ref(''),fieldError=ref('');
const form=reactive({name:'',datasetId:'contacts',operation:'clean',simulateFailure:false});
const operations={clean:'数据清洗',validate:'邮箱校验',normalize:'格式标准化'};
const states={all:'全部任务',running:'处理中',queued:'排队中',succeeded:'已完成',failed:'失败',cancelled:'已取消'};
const pageNames={tasks:'任务中心',datasets:'数据集',activity:'操作记录'};
const date=v=>v?new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v)):'—';
const sourceName=id=>datasets.value.find(d=>d.id===id)?.name||id;
const selectedDataset=computed(()=>datasets.value.find(d=>d.id===form.datasetId));
const activeCount=computed(()=>summary.value.running+summary.value.queued);
const anySelected=computed(()=>selected.value.length>0);
let interval,debounce,toastTimer,controller,seq=0;
async function api(url,opts={}){const r=await fetch('/api'+url,{...opts,headers:{'Content-Type':'application/json',...opts.headers}});let data;try{data=await r.json();}catch{throw Error('服务返回了无法读取的数据，请重试。');}if(!r.ok){const e=Error(data.message||'请求未完成，请重试。');e.field=data.field;throw e;}return data;}
function notify(message,type='success'){clearTimeout(toastTimer);toast.value={message,type};toastTimer=setTimeout(()=>toast.value=null,5000);}
async function loadTasks(quiet=false){const requestSeq=++seq;controller?.abort();controller=new AbortController();if(!quiet)loading.value=true;try{const params=new URLSearchParams({q:q.value,status:status.value,operation:operation.value,page:String(page.value),pageSize:String(pageSize.value)});const d=await api('/tasks?'+params,{signal:controller.signal});if(requestSeq!==seq)return;taskList.value=d.items;summary.value=d.summary;total.value=d.total;pages.value=d.pages;page.value=d.page;selected.value=selected.value.filter(id=>d.items.some(t=>t.id===id));error.value='';connected.value=true;updated.value=new Date();}catch(e){if(e.name==='AbortError')return;error.value='无法连接本地服务。请确认服务正在运行，再点击重试。';connected.value=false;}finally{if(requestSeq===seq)loading.value=false;}}
async function loadPage(){if(pageView.value==='tasks')return loadTasks();try{loading.value=true;error.value='';const d=await api(pageView.value==='datasets'?'/datasets':'/activity');if(pageView.value==='datasets')datasets.value=d.items;else activity.value=d.items;connected.value=true;}catch(e){error.value=e.message;connected.value=false;}finally{loading.value=false;}}
function navigate(){const v=location.hash.slice(1);pageView.value=['tasks','datasets','activity'].includes(v)?v:'tasks';loadPage();}
watch([status,operation,pageSize],()=>{page.value=1;loadTasks();});watch(q,()=>{clearTimeout(debounce);debounce=setTimeout(()=>{page.value=1;loadTasks();},250);});
function setPage(n){if(n<1||n>pages.value)return;page.value=n;loadTasks();}
function clearFilters(){q.value='';status.value='all';operation.value='all';page.value=1;loadTasks();}
function toggleAll(e){selected.value=e.target.checked?taskList.value.map(t=>t.id):[];}
async function openCreate(datasetId){form.name='';form.datasetId=datasetId||datasets.value[0]?.id||'contacts';form.operation='clean';form.simulateFailure=false;formError.value='';fieldError.value='';createOpen.value=true;createDialog.value.showModal();await nextTick();createDialog.value.querySelector('input')?.focus();}
function closeCreate(){if(submitting.value)return;createDialog.value.close();createOpen.value=false;}
async function createTask(){if(submitting.value)return;formError.value='';fieldError.value='';if(form.name.trim().length<2){fieldError.value='name';formError.value='请输入至少 2 个字符的任务名称。';await nextTick();createDialog.value.querySelector('input').focus();return;}submitting.value=true;try{const d=await api('/tasks',{method:'POST',body:JSON.stringify(form)});createDialog.value.close();createOpen.value=false;q.value='';status.value='all';operation.value='all';page.value=1;if(pageView.value!=='tasks')location.hash='tasks';await loadTasks();notify('任务已创建，后端将按顺序执行。');await openDetail(d.task.id);}catch(e){formError.value=e.message;fieldError.value=e.field||'';}finally{submitting.value=false;}}
async function openDetail(id){busy[id]=true;try{const d=await api('/tasks/'+id);detail.value=d.task;detailDialog.value.showModal();}catch(e){notify(e.message,'error');}finally{busy[id]=false;}}
async function refreshDetail(){if(!detailDialog.value?.open||!detail.value)return;const id=detail.value.id;try{const d=await api('/tasks/'+id);if(detail.value?.id===id&&detailDialog.value?.open)detail.value=d.task;}catch{} }
async function taskAction(task,action){if(busy[task.id])return;busy[task.id]=true;try{const d=await api(`/tasks/${task.id}/${action}`,{method:'POST'});if(detail.value?.id===task.id)detail.value=d.task;await loadTasks(true);notify(action==='retry'?'任务已重新排队。':'任务已取消。');}catch(e){notify(e.message,'error');}finally{busy[task.id]=false;}}
async function download(task){if(busy[task.id])return;busy[task.id]=true;try{const r=await fetch(`/api/tasks/${task.id}/result`);if(!r.ok){const d=await r.json();throw Error(d.message);}const blob=await r.blob();saveBlob(blob,task.id+'-result.csv');notify('结果文件已下载。');}catch(e){notify(e.message||'下载失败，请重试。','error');}finally{busy[task.id]=false;}}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportList(){const rows=anySelected.value?taskList.value.filter(t=>selected.value.includes(t.id)):taskList.value;const escape=v=>'"'+String(v).replaceAll('"','""')+'"';const csv=[['任务编号','任务名称','处理方式','状态','数据量'],...rows.map(t=>[t.id,t.name,operations[t.operation],states[t.status],t.total])].map(r=>r.map(escape).join(',')).join('\r\n');saveBlob(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),'任务列表.csv');notify(`已导出 ${rows.length} 条任务记录。`);}
async function previewDataset(id){try{datasetDetail.value=await api('/datasets/'+id);datasetDialog.value.showModal();}catch(e){notify(e.message,'error');}}
function cancelEscape(event){if(submitting.value)event.preventDefault();}
function shortcuts(event){if(event.key==='/'&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!document.activeElement?.isContentEditable&&!document.querySelector('dialog[open]')&&pageView.value==='tasks'){event.preventDefault();document.querySelector('.search-field input')?.focus();}}
onMounted(async()=>{window.addEventListener('hashchange',navigate);window.addEventListener('keydown',shortcuts);try{datasets.value=(await api('/datasets')).items;}catch{}await loadPage();interval=setInterval(()=>{if(document.hidden||createOpen.value)return;if(pageView.value==='tasks')loadTasks(true);if(detailDialog.value?.open)refreshDetail();},2000);});
onUnmounted(()=>{window.removeEventListener('hashchange',navigate);window.removeEventListener('keydown',shortcuts);clearInterval(interval);clearTimeout(debounce);clearTimeout(toastTimer);controller?.abort();});
</script>
<template>
<div class="app-shell">
<aside class="sidebar"><a class="brand" href="#tasks"><span class="brand-mark"><i></i><i></i><i></i></span><strong>序列<span>SEQUENCE</span></strong></a><div class="workspace"><span class="workspace-avatar">序</span><div><strong>演示工作区</strong><small>本地沙盒</small></div><span class="workspace-tag">LOCAL</span></div><div class="nav-label">工作空间</div><nav aria-label="工作空间导航"><a v-for="(label,key) in pageNames" :key="key" :href="'#'+key" :class="{active:pageView===key}" :aria-current="pageView===key?'page':undefined"><Icon :name="key==='tasks'?'tasks':key==='datasets'?'database':'activity'"/><span>{{label}}</span><span v-if="key==='tasks'" class="nav-count">{{summary.total}}</span></a></nav><div class="sidebar-bottom"><div class="sandbox-note"><p>放心试一试<br><span>仅处理本地示例数据</span></p></div><button class="nav-help" @click="aboutDialog.showModal()"><Icon name="settings" :size="17"/>关于这个演示</button><div class="user"><span class="avatar">访</span><div><strong>体验访客</strong><small>本地工作空间</small></div><span class="user-dot"></span></div></div></aside>
<div class="main-shell"><header class="topbar"><div class="breadcrumb">工作空间 <Icon name="chevron" :size="13"/><strong>{{pageNames[pageView]}}</strong></div><div class="top-right"><span class="connection" :class="{offline:!connected}"><span></span>{{connected?'本地服务已连接':'连接中断'}}</span><span class="top-divider"></span><button class="icon-button" aria-label="查看演示说明" @click="aboutDialog.showModal()"><Icon name="info"/></button><span class="avatar avatar-small">访</span></div></header>
<main>
<div class="page-heading"><div><div class="heading-line"><h1>{{pageNames[pageView]}}</h1><span class="subtle-label">{{pageView==='tasks'?'TASKS':pageView==='datasets'?'DATASETS':'ACTIVITY'}}</span></div><p>{{pageView==='tasks'?'把重复的数据工作交给任务，让每一步都有迹可循。':pageView==='datasets'?'选择一份示例数据，预览内容，再开始处理。':'从创建到完成，查看工作区里发生的每一次变化。'}}</p></div><button class="button primary" @click="openCreate()"><Icon name="plus" :size="17"/>新建任务</button></div>
<template v-if="pageView==='tasks'">
<div class="overview"><div class="overview-intro"><div><strong>工作区概览</strong><span>所有任务的实时状态</span></div></div><div class="overview-stat"><span>进行中</span><strong>{{activeCount}}<small>个任务</small></strong></div><div class="overview-stat"><span>已完成</span><strong>{{summary.succeeded}}<small>个任务</small></strong></div><div class="overview-stat"><span>需要关注</span><strong :class="{attention:summary.failed}">{{summary.failed}}<small>个失败</small></strong></div><div class="overview-end"><span class="live-dot"></span>每 2 秒自动同步</div></div>
<section class="task-panel" aria-label="任务列表"><div class="panel-tabs" role="group" aria-label="按任务状态筛选"><button v-for="key in ['all','running','succeeded','failed']" :key="key" :class="{selected:status===key}" :aria-pressed="status===key" @click="status=key">{{states[key]}}<span>{{key==='all'?summary.total:summary[key]}}</span></button><div class="panel-tabs-end"><Icon name="clock" :size="13"/><span>{{updated?'刚刚同步':'等待同步'}}</span></div></div>
<div class="toolbar"><label class="search-field"><Icon name="search" :size="17"/><input v-model="q" type="search" aria-label="搜索任务名称或编号" placeholder="搜索任务名称或编号…"><kbd>/</kbd></label><label class="select-field"><span class="sr-only">处理方式</span><Icon name="filter" :size="15"/><select v-model="operation" aria-label="处理方式"><option value="all">全部处理方式</option><option v-for="(label,key) in operations" :value="key" :key="key">{{label}}</option></select></label><div class="toolbar-spacer"></div><button class="button ghost" :disabled="loading||!taskList.length" @click="exportList"><Icon name="download" :size="16"/>{{anySelected?'导出选中':'导出本页'}}</button><button class="icon-button bordered" aria-label="刷新任务列表" :disabled="loading" @click="loadTasks()"><Icon name="refresh" :size="16" :class="{spin:loading}"/></button></div>
<div v-if="error" class="error-state" role="alert"><Icon name="info"/><div><strong>暂时无法获取任务</strong><p>{{error}}</p></div><button class="button" @click="loadTasks()">重试</button></div>
<div class="table-scroll" v-else><table class="tasks-table"><caption class="sr-only">任务列表，包含处理方式、状态、数据量、创建时间及操作</caption><thead><tr><th class="checkbox-cell"><input type="checkbox" aria-label="选择本页全部任务" :checked="taskList.length>0&&selected.length===taskList.length" :disabled="loading||!taskList.length" @change="toggleAll"></th><th class="task-name-column">任务名称</th><th>处理方式</th><th class="status-column">状态 / 进度</th><th class="align-right">数据量</th><th>创建时间</th><th class="align-right action-column">操作</th></tr></thead><tbody v-if="loading"><tr v-for="n in 6" :key="n" class="loading-row"><td colspan="7"><div class="skeleton"></div></td></tr></tbody><tbody v-else><tr v-for="task in taskList" :key="task.id" :class="{checked:selected.includes(task.id)}"><td class="checkbox-cell"><input v-model="selected" :value="task.id" type="checkbox" :aria-label="'选择任务 '+task.name"></td><td><button class="task-name" @click="openDetail(task.id)">{{task.name}}</button><div class="task-subline"><span class="task-code">{{task.id}}</span><span class="middle-dot">·</span>{{sourceName(task.datasetId)}}</div></td><td><span class="operation-label">{{operations[task.operation]}}</span></td><td><div class="status-wrap"><StatusBadge :status="task.status"/><span v-if="task.status==='running'" class="percent">{{task.progress}}%</span></div><div v-if="task.status==='running'" class="mini-progress" role="progressbar" :aria-valuenow="task.progress" aria-valuemin="0" aria-valuemax="100" :aria-label="task.name+'进度'"><span :style="{width:task.progress+'%'}"></span></div></td><td class="align-right numeric">{{task.total.toLocaleString()}}<span class="unit">条</span></td><td class="time-cell">{{date(task.createdAt)}}</td><td><div class="row-actions"><button v-if="task.status==='failed'" class="text-button retry" :disabled="busy[task.id]" @click="taskAction(task,'retry')"><Icon name="refresh" :size="14"/>重试</button><button v-else-if="task.status==='succeeded'" class="icon-button" :aria-label="'下载 '+task.name+' 的结果'" :disabled="busy[task.id]" @click="download(task)"><Icon name="download" :size="16"/></button><button class="text-button" :disabled="busy[task.id]" @click="openDetail(task.id)">详情<Icon name="chevron" :size="12"/></button></div></td></tr></tbody></table><div v-if="!loading&&!taskList.length" class="empty-state"><span class="empty-icon"><Icon name="search" :size="25"/></span><h3>没有找到匹配的任务</h3><p>试试其他关键词，或清除筛选条件查看全部任务。</p><button class="button" @click="clearFilters">清除筛选</button></div></div>
<div class="table-footer"><span v-if="anySelected">已选择 {{selected.length}} 条</span><span v-else>共 {{total}} 个任务<span class="footer-hint"> · 历史记录为演示数据</span></span><div class="pagination"><label>每页 <select v-model.number="pageSize" aria-label="每页显示条数"><option :value="8">8 条</option><option :value="16">16 条</option><option :value="25">25 条</option></select></label><button class="icon-button" :disabled="page<=1||loading" aria-label="上一页" @click="setPage(page-1)"><Icon class="flip" name="chevron" :size="15"/></button><span class="page-number">{{page}}<span> / {{pages}}</span></span><button class="icon-button" :disabled="page>=pages||loading" aria-label="下一页" @click="setPage(page+1)"><Icon name="chevron" :size="15"/></button></div></div></section>
<div class="bottom-note"><span>任务在后台依次执行，关闭详情不会中断处理。</span><span class="bottom-note-right">支持 CSV 结果下载</span></div>
</template>
<template v-else-if="pageView==='datasets'"><section class="task-panel dataset-panel"><div class="section-title"><h2>可用数据集 <span>{{datasets.length}}</span></h2><span>内置示例 · 不含真实用户数据</span></div><div v-if="error" class="error-state" role="alert">{{error}}<button class="button" @click="loadPage">重试</button></div><table v-else><thead><tr><th>数据集</th><th>记录数</th><th>更新时间</th><th class="align-right">操作</th></tr></thead><tbody><tr v-for="d in datasets" :key="d.id"><td><div class="dataset-name"><span><Icon name="database" :size="21"/></span><div><strong>{{d.name}}</strong><p>{{d.description}}</p></div></div></td><td class="numeric">{{d.count}} 条</td><td class="time-cell">{{d.updated}}</td><td><div class="row-actions"><button class="text-button" @click="previewDataset(d.id)">预览数据</button><button class="button small" @click="openCreate(d.id)">创建任务<Icon name="arrow" :size="14"/></button></div></td></tr></tbody></table></section></template>
<template v-else><section class="task-panel"><div class="section-title"><h2>最近操作</h2><button class="button ghost" @click="loadPage"><Icon name="refresh" :size="15"/>刷新</button></div><div v-if="error" class="error-state" role="alert">{{error}}<button class="button" @click="loadPage">重试</button></div><div v-else class="activity-list"><div v-for="item in activity" :key="item.id" class="activity-item"><span class="activity-icon"><Icon :name="item.action==='处理完成'?'check':item.action==='执行失败'?'info':'activity'" :size="16"/></span><div><strong>{{item.action}}</strong><button @click="openDetail(item.taskId)">{{item.taskName}}</button><span>{{item.taskId}}</span></div><time>{{date(item.at)}}</time></div><div v-if="!activity.length&&!loading" class="empty-state"><h3>还没有操作记录</h3><p>创建第一个任务后，执行过程会记录在这里。</p></div></div></section></template>
<footer class="page-footer"><span class="footer-logo">序列<span> / 把重复的事，有序完成。</span></span><span>Vue + 本地 API · 交互演示</span></footer>
</main></div>
<div v-if="toast" class="toast" :class="toast.type" role="status"><Icon :name="toast.type==='error'?'info':'check'" :size="17"/><span>{{toast.message}}</span><button class="icon-button" aria-label="关闭提示" @click="toast=null"><Icon name="close" :size="14"/></button></div>
<dialog ref="createDialog" class="create-dialog" aria-labelledby="create-title" @cancel="cancelEscape" @close="createOpen=false"><form @submit.prevent="createTask" novalidate><div class="dialog-heading"><div><h2 id="create-title">新建处理任务</h2><p>选择数据与处理方式，剩下的交给后台。</p></div><button type="button" class="icon-button" aria-label="关闭新建任务" :disabled="submitting" @click="closeCreate"><Icon name="close"/></button></div><div class="form-body"><label class="field"><span>任务名称 <em>*</em></span><input v-model.trim="form.name" maxlength="60" placeholder="例如：十一月客户数据清洗" :aria-invalid="fieldError==='name'" :aria-describedby="fieldError==='name'?'form-error':undefined" :disabled="submitting"><small>{{form.name.length}} / 60 字符</small></label><label class="field"><span>选择数据集 <em>*</em></span><select v-model="form.datasetId" :disabled="submitting"><option v-for="d in datasets" :key="d.id" :value="d.id">{{d.name}} · {{d.count}} 条</option></select><small>{{selectedDataset?.description}}</small></label><label class="field"><span>处理方式 <em>*</em></span><select v-model="form.operation" :disabled="submitting"><option v-for="(label,key) in operations" :value="key" :key="key">{{label}}</option></select><small>{{form.operation==='clean'?'去除首尾空白、统一邮箱大小写、剔除无效邮箱并按邮箱去重。':form.operation==='validate'?'统一字段格式并剔除无效邮箱，保留重复记录。':'去除字段首尾空白、统一邮箱大小写，保留所有记录。'}}</small></label><div class="form-summary"><div><strong>结果将导出为 CSV</strong><p>输入 {{selectedDataset?.count||0}} 条记录，处理后可在任务详情下载。</p></div></div><details class="advanced"><summary>演示选项</summary><label><input type="checkbox" v-model="form.simulateFailure" :disabled="submitting"><span>首次执行模拟数据源中断<small>用于体验失败与重试，再次执行会成功。</small></span></label></details><p v-if="formError" class="form-error" role="alert" id="form-error"><Icon name="info" :size="15"/>{{formError}}</p></div><div class="dialog-footer"><span>后台依次执行</span><button type="button" class="button" :disabled="submitting" @click="closeCreate">取消</button><button type="submit" class="button primary" :disabled="submitting"><Icon :name="submitting?'refresh':'plus'" :class="{spin:submitting}" :size="16"/>{{submitting?'正在创建…':'创建并执行'}}</button></div></form></dialog>
<dialog ref="detailDialog" class="detail-dialog" aria-labelledby="detail-title"><template v-if="detail"><div class="dialog-heading"><div><span class="detail-code">{{detail.id}}<span>第 {{detail.attempts}} 次执行</span></span><h2 id="detail-title">{{detail.name}}</h2></div><button class="icon-button" aria-label="关闭任务详情" @click="detailDialog.close()"><Icon name="close"/></button></div><div class="detail-body"><div class="detail-status"><StatusBadge :status="detail.status"/><span>{{['running','queued'].includes(detail.status)?'状态自动更新':'任务已结束'}}</span></div><div class="stage-flow" aria-label="执行阶段"><div v-for="(label,i) in ['读取数据','执行处理','导出结果']" :key="label" :class="{done:detail.status==='succeeded'||(i===0&&detail.progress>0)||(i===1&&detail.progress===100),current:(i===0&&detail.status==='queued')||(i===1&&detail.status==='running'),failed:i===1&&detail.status==='failed'}"><span><Icon v-if="detail.status==='succeeded'||(i===0&&detail.progress>0)" name="check" :size="13"/><Icon v-else-if="i===1&&detail.status==='failed'" name="close" :size="13"/><span v-else>{{i+1}}</span></span><strong>{{label}}</strong></div></div><div v-if="detail.status==='running'" class="detail-progress"><div><span>正在处理记录</span><strong>{{detail.processed}} / {{detail.total}}</strong></div><div class="progress-track" role="progressbar" aria-label="任务处理进度" :aria-valuenow="detail.progress" aria-valuemin="0" aria-valuemax="100"><span :style="{width:detail.progress+'%'}"></span></div></div><div v-if="detail.status==='failed'" class="inline-error"><Icon name="info" :size="18"/><div><strong>本次处理未完成</strong><p>{{detail.error}}</p></div></div><div v-if="detail.status==='succeeded'" class="result-summary"><Icon name="check" :size="20"/><div><strong>处理完成，结果已就绪</strong><p>保留 {{detail.resultCount}} 条 · 无效 {{detail.rejected}} 条 · 去重 {{detail.duplicates}} 条</p></div></div><dl class="detail-facts"><div><dt>数据集</dt><dd>{{sourceName(detail.datasetId)}}</dd></div><div><dt>处理方式</dt><dd>{{operations[detail.operation]}}</dd></div><div><dt>输入记录</dt><dd>{{detail.total}} 条</dd></div><div><dt>创建时间</dt><dd>{{date(detail.createdAt)}}</dd></div></dl><h3 class="detail-section-title">执行日志 <span>{{detail.logs.length}}</span></h3><ol class="logs"><li v-for="(entry,i) in detail.logs" :key="i" :class="entry.level"><time>{{date(entry.at)}}</time><p>{{entry.message}}</p></li></ol><template v-if="detail.preview?.length"><h3 class="detail-section-title">结果预览 <span>前 {{detail.preview.length}} 条</span></h3><div class="preview-table"><table><thead><tr><th>姓名</th><th>邮箱</th><th>地区</th></tr></thead><tbody><tr v-for="(r,i) in detail.preview" :key="i"><td>{{r.name}}</td><td>{{r.email}}</td><td>{{r.region}}</td></tr></tbody></table></div></template></div><div class="dialog-footer detail-actions"><button v-if="['running','queued'].includes(detail.status)" class="button danger" :disabled="busy[detail.id]" @click="taskAction(detail,'cancel')"><Icon name="stop" :size="14"/>取消任务</button><span v-else></span><button v-if="detail.status==='failed'" class="button primary" :disabled="busy[detail.id]" @click="taskAction(detail,'retry')"><Icon name="refresh" :size="15"/>重新执行</button><button v-else-if="detail.status==='succeeded'" class="button primary" :disabled="busy[detail.id]" @click="download(detail)"><Icon name="download" :size="16"/>下载结果 CSV</button><button v-else class="button" @click="detailDialog.close()">关闭详情</button></div></template></dialog>
<dialog ref="datasetDialog" class="dataset-dialog" aria-labelledby="dataset-title"><template v-if="datasetDetail"><div class="dialog-heading"><div><h2 id="dataset-title">{{datasetDetail.name}}</h2><p>{{datasetDetail.count}} 条示例记录 · 预览前 8 条原始数据</p></div><button class="icon-button" aria-label="关闭数据预览" @click="datasetDialog.close()"><Icon name="close"/></button></div><div class="form-body"><div class="preview-table"><table><thead><tr><th>姓名</th><th>邮箱</th><th>地区</th></tr></thead><tbody><tr v-for="(r,i) in datasetDetail.rows" :key="i"><td>{{r.name}}</td><td>{{r.email}}</td><td>{{r.region}}</td></tr></tbody></table></div><p class="muted">原始数据中刻意保留了空白、重复项和无效邮箱，便于观察处理结果。</p></div><div class="dialog-footer"><span></span><button class="button primary" @click="datasetDialog.close();openCreate(datasetDetail.id)">用此数据创建任务<Icon name="arrow" :size="16"/></button></div></template></dialog>
<dialog ref="aboutDialog" class="about-dialog" aria-labelledby="about-title"><div class="dialog-heading"><div><h2 id="about-title">关于序列</h2><p>一页真实可用的工具平台演示。</p></div><button class="icon-button" aria-label="关闭演示说明" @click="aboutDialog.close()"><Icon name="close"/></button></div><div class="form-body"><p>Vue 3 前端通过本机 HTTP API 创建任务。后端读取示例数据，逐批处理、保存状态，并生成可下载的 CSV。</p><p>内置历史记录为演示数据。新建任务的进度、结果和日志来自实际处理；重启后仍会保留。</p><p>本演示没有账号系统、外部数据源或生产权限隔离，仅供本机体验。</p><div class="about-stack"><span>Vue 3</span><span>Vite</span><span>Node.js</span><span>本地 JSON</span></div></div><div class="dialog-footer"><span></span><button class="button primary" @click="aboutDialog.close()">明白了</button></div></dialog>
</div>
</template>
